package com.nextfeet.nextfeet.controller; import jakarta.servlet.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import com.nextfeet.nextfeet.model.Usuario; import com.nextfeet.nextfeet.service.UsuarioService; @Controller public class AuthController {private final UsuarioService service; public AuthController(UsuarioService service){this.service=service;} @GetMapping({"/","/login"}) public String login(){return "login";} @PostMapping("/login") public String ingresar(@RequestParam String correo,@RequestParam String password,HttpSession s,Model m){Usuario u=service.login(correo,password);if(u==null){m.addAttribute("error","Credenciales inválidas o cuenta inactiva");return "login";}s.setAttribute("usuario",u);return "ADMIN".equals(u.getRol())?"redirect:/admin/dashboard":"redirect:/home";} @GetMapping("/registro") public String registro(Model m){m.addAttribute("usuario",new Usuario());return "registro";} @PostMapping("/registro") public String registrar(@ModelAttribute Usuario u){u.setRol("CLIENTE");service.registrar(u);return "redirect:/login";} @GetMapping("/logout") public String logout(HttpSession s){s.invalidate();return "redirect:/login";} }